import { styled, Text } from '@tamagui/web';
import type { AriaAttributes, ReactNode } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { DivAttributes } from '../../types/ElementAttributes';

export type TileProps = {
	children?: ReactNode;
	elevation?: '0' | '1' | '2' | '1nb' | '2nb';
	/** Drops the default padding, for a surface whose content brings its own. */
	flush?: boolean;
} & DivAttributes &
	Pick<AriaAttributes, 'aria-label' | 'aria-labelledby'>;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const tileFrame = {
	flexBasis: 'auto',
	whiteSpace: 'inherit',
	wordWrap: 'inherit',
	render: 'div',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	color: 'var(--rcx-color-font-default, #2f343d)',
	borderRadius: 'var(--rcx-tile-border-radius, 0.25rem)',
	backgroundColor: 'var(--rcx-color-surface-light, #ffffff)',
	fontSize: '0.875rem',
	fontWeight: 400,
	lineHeight: '1.25rem',
	letterSpacing: '0rem',
} as const;

const tileDensities = {
	regular: {
		padding: '16px',
	},
	flush: {
		padding: 0,
	},
} as const;

const tileElevations = {
	'0': {
		boxShadow: 'none',
	},
	'1': {
		boxShadow: '0px 0px 12px 0px var(--rcx-color-shadow-elevation-1, #2f343d1a)',
		borderWidth: '1px',
		borderStyle: 'solid',
		borderColor: 'var(--rcx-color-shadow-elevation-border, #ebecef)',
	},
	'2': {
		boxShadow:
			'0px 0px 2px 0px var(--rcx-color-shadow-elevation-2x, #2f343d14), 0px 0px 12px 0px var(--rcx-color-shadow-elevation-2y, #2f343d1f)',
		borderWidth: '1px',
		borderStyle: 'solid',
		borderColor: 'var(--rcx-color-shadow-elevation-border, #ebecef)',
	},
	'1nb': {},
	'2nb': {},
} as const;

// end of generated

const TileFrame = styled(Text, {
	...tileFrame,
	variants: {
		density: tileDensities,
		elevation: tileElevations,
	},
});

function Tile(props: TileProps) {
	const { elevation = '1', flush, className, children } = props;

	return (
		<TileFrame
			density={flush ? 'flush' : 'regular'}
			elevation={elevation}
			className={prependClassName(
				className,
				`rcx-box rcx-box--full ${flush ? 'rcx-tile--flush ' : ''}rcx-tile--elevation-${elevation} rcx-tile`,
			)}
			render={<div {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} />}
		>
			{children}
		</TileFrame>
	);
}

export default Tile;
